{
  "name": "套接字通信器",
  "name_en": "Socket Communicator",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用于把网络套接字封装成类似文件的读写接口，方便实验控制框架通过套接字与仪器或远程服务交换原始字节数据，并管理地址、终止符、超时、输入缓冲区和连接关闭等通信属性。",
  "description_en": "This is a non-physical software communication component that wraps a network socket as a file-like I/O interface, allowing a laboratory control framework to exchange raw byte data with instruments or remote services over sockets while managing address, terminator, timeout, input buffer flushing, and connection closure.",
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取/设置套接字对端地址",
      "description_en": "get/set socket peer address"
    },
    {
      "action_name": "auto-close",
      "description": "关闭套接字连接",
      "description_en": "close the socket connection"
    },
    {
      "action_name": "auto-flush_input",
      "description": "清空输入缓冲区",
      "description_en": "flush the input buffer"
    },
    {
      "action_name": "auto-read_raw",
      "description": "从套接字读取原始字节数据",
      "description_en": "read raw bytes from the socket"
    },
    {
      "action_name": "auto-seek",
      "description": "移动输入数据源位置（此通信器未实现）",
      "description_en": "seek the input data source position (not implemented for this communicator)"
    },
    {
      "action_name": "auto-tell",
      "description": "获取当前输入数据位置（此通信器未实现）",
      "description_en": "get the current input data position (not implemented for this communicator)"
    },
    {
      "action_name": "auto-terminator",
      "description": "获取/设置消息终止符",
      "description_en": "get/set message terminator"
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置套接字通信超时",
      "description_en": "get/set socket communication timeout"
    },
    {
      "action_name": "auto-write_raw",
      "description": "向套接字写入原始字节数据",
      "description_en": "write raw bytes to the socket"
    }
  ],
  "tag_hints": [
    "socket communication",
    "TCP/IP instrument control",
    "file-like I/O",
    "raw byte stream",
    "timeout handling",
    "input buffer flushing"
  ]
}

